SELECT procurement_group_id,representative_date,representative_title,demand_institution_name,detailed_product_class_no,detailed_product_class_name,item_category,representative_winner_name,representative_award_amount,representative_award_rate,representative_contract_name,representative_contract_amount,bid_count,award_count,contract_count,match_status FROM procurement_group WHERE (?1='' OR representative_title LIKE ?2 OR demand_institution_name LIKE ?2 OR detailed_product_class_no LIKE ?2 OR representative_winner_name LIKE ?2 OR representative_contract_name LIKE ?2 OR EXISTS(SELECT 1 FROM search_classes sc JOIN procurement_group_member m ON m.source_type=sc.domain AND m.source_id=sc.source_id WHERE m.procurement_group_id=procurement_group.procurement_group_id AND (sc.classification_no LIKE ?2 OR sc.detailed_no LIKE ?2 OR sc.product_id LIKE ?2 OR sc.classification_name LIKE ?2 OR sc.detailed_name LIKE ?2))) AND (?3='all' OR item_category=?3) ORDER BY representative_date DESC,procurement_group_id DESC LIMIT ?4